(function(){
 const status=document.querySelector('#setup-status');let busy=false,audioUrl=null;
 const notice=text=>status.textContent=text;
 async function request(path,body){const response=await fetch(path,{method:body===undefined?'GET':'POST',headers:{Accept:'application/json',...(body===undefined?{}:{'Content-Type':'application/json'})},credentials:'same-origin',cache:'no-store',redirect:'error',signal:AbortSignal.timeout(60000),...(body===undefined?{}:{body:JSON.stringify(body)})});if(!response.ok){let data;try{data=await response.json()}catch{}throw Error(data?.error||'Request failed. Retry.');}return response;}
 async function action(fn){if(busy)return;busy=true;try{await fn();}catch(error){notice(error.message||'Request failed.');}finally{busy=false;}}
 function linkResults(container,items){container.replaceChildren();for(const item of items){let url;try{url=new URL(item.url);}catch{continue;}if(url.protocol!=='https:'||url.username||url.password)continue;const a=document.createElement('a');a.href=url.href;a.rel='noopener noreferrer';a.target='_blank';a.textContent=item.title;container.append(a);if(item.snippet){const p=document.createElement('p');p.textContent=item.snippet;container.append(p);}}}
 document.querySelector('#search-form').addEventListener('submit',event=>{event.preventDefault();action(async()=>{notice('Searching…');const data=await(await request('/api/search',{query:document.querySelector('#search-query').value.trim()})).json();linkResults(document.querySelector('#search-results'),data.results);notice(data.results.length+' source links found.');});});
 document.querySelector('#github-list').addEventListener('click',()=>action(async()=>{notice('Loading repositories…');const data=await(await request('/api/connectors/github',{action:'list-repositories'})).json();linkResults(document.querySelector('#github-results'),data.repositories.map(r=>({url:r.url,title:r.name,snippet:r.description})));notice('Repository list loaded.');}));
 const video=document.querySelector('#media-preview');const media=DuaMediaSession({preview:video,onState:state=>{video.hidden=state.status!=='active';notice(state.error||(state.status==='active'?'Local '+state.mode+' preview active.':state.status==='requesting'?'Choose capture permission…':'Preview stopped.'));}});
 document.querySelector('#start-camera').addEventListener('click',()=>action(()=>media.startCamera()));document.querySelector('#start-screen').addEventListener('click',()=>action(()=>media.startScreen()));document.querySelector('#stop-media').addEventListener('click',()=>media.stop());
 const audio=document.querySelector('#voice-audio');
 document.querySelector('#voice-generate').addEventListener('click',()=>action(async()=>{const text=document.querySelector('#voice-text').value.trim();if(!text)throw Error('Enter text to speak.');notice('Generating audio…');const response=await request('/api/voice/audio',{text});const blob=await response.blob();if(blob.size>10*1024*1024)throw Error('Audio response is too large.');audio.pause();if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=URL.createObjectURL(blob);audio.src=audioUrl;audio.hidden=false;notice('Audio ready. Press Play to listen.');}));
 window.addEventListener('pagehide',()=>{media.stop();audio.pause();if(audioUrl)URL.revokeObjectURL(audioUrl);});
 action(async()=>{const data=await(await request('/api/setup')).json();const container=document.querySelector('#setup-groups');for(const group of data.groups){const section=document.createElement('section');section.className='local-card';const h=document.createElement('h2');h.textContent=group.title;const state=document.createElement('p');state.className='setup-state';state.textContent=group.state.replaceAll('-',' ');section.append(h,state);for(const line of group.limitations){const p=document.createElement('p');p.textContent=line;section.append(p);}container.append(section);}document.querySelector('#search-submit').disabled=!data.search.configured;const account=await DuaAccount.load();document.querySelector('#github-list').disabled=!account.user||!data.groups.find(g=>g.id==='connectors')||data.groups.find(g=>g.id==='connectors').state!=='configured';document.querySelector('#voice-generate').disabled=!account.user||!data.account.ownerRestricted||!data.advanced.voice?.generatedAudio?.configured;notice('Setup loaded. Configuration does not guarantee live provider access.');});
})();
